import { useEffect, useRef, type ReactNode } from 'react';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { PageHeader } from '@kerfjs/ui/page-header';
import { ResizableRegion, wireResizableRegions } from '@kerfjs/ui/resizable-region';
import '@kerfjs/ui/layout.css';
import './application-shell.css';

type Props = {
  section: string;
  inspectorWidth: number;
  onNavigate: (section: string) => void;
  onInspectorWidthChange: (width: number) => void;
  workspace: ReactNode;
  inspector: ReactNode;
};
export function ApplicationShell(props: Props) {
  const root = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!root.current) return;
    const dispose = wireResizableRegions(root.current);
    return () => dispose();
  }, []);
  return <div ref={root} className="kui-layout app-shell">
    <a className="skip-link" href="#workspace">Skip to workspace</a>
    <Toolbar><strong>Workspace</strong><a href="#navigation">Navigation</a><a href="#inspector">Inspector</a></Toolbar>
    <div className="app-panes">
      <nav id="navigation" aria-label="Workspace navigation" className="kui-sidebar app-navigation">
        <section className="kui-sidebar-section" aria-label="Work">
          <MenuHeader label="Work" />
          <MenuItem label="Overview" selected={props.section === 'overview'} onClick={() => props.onNavigate('overview')} />
          <MenuItem label="Projects" selected={props.section === 'projects'} onClick={() => props.onNavigate('projects')} />
        </section>
        <section className="kui-sidebar-section" aria-label="Manage">
          <MenuHeader label="Manage" />
          <MenuItem label="Settings" selected={props.section === 'settings'} onClick={() => props.onNavigate('settings')} />
        </section>
      </nav>
      <main id="workspace" tabIndex={-1} className="app-workspace">
        <PageHeader title="Workspace" />
        <div className="kui-pane-body app-workspace-scroll" tabIndex={0} aria-label="Workspace content">{props.workspace}</div>
      </main>
      <ResizableRegion className="app-inspector" size={props.inspectorWidth} minSize={240} maxSize={480} onSizeChange={props.onInspectorWidthChange} aria-label="Resize inspector" controls="inspector">
        <aside id="inspector" tabIndex={-1} aria-label="Inspector">
          <PageHeader title="Inspector" />
          <div className="kui-pane-body app-inspector-scroll" tabIndex={0} aria-label="Inspector content">{props.inspector}</div>
        </aside>
      </ResizableRegion>
    </div>
  </div>;
}
// The application supplies routing, content, controlled width, and persistence.
// Component prop spellings require checking against the installed package declarations.

