.app-shell { block-size: 100dvh; display: flex; flex-direction: column; overflow: hidden; }
.app-panes { flex: 1; min-block-size: 0; display: flex; }
.app-navigation { flex: 0 0 14rem; overflow: auto; }
.app-workspace { flex: 1; min-inline-size: 0; display: flex; flex-direction: column; }
.app-workspace-scroll, .app-inspector-scroll { flex: 1; min-block-size: 0; overflow: auto; overflow-wrap: anywhere; }
.app-inspector { min-inline-size: 0; }
.app-inspector aside { block-size: 100%; display: flex; flex-direction: column; min-block-size: 0; }
.skip-link { position: absolute; transform: translateY(-200%); }
.skip-link:focus { transform: none; z-index: 10; }
.app-shell :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
@media (max-width: 48rem) {
  .app-shell { block-size: auto; min-block-size: 100dvh; overflow: visible; }
  .app-panes { display: flex; flex-direction: column; }
  .app-navigation { flex-basis: auto; overflow: visible; }
  .app-workspace-scroll, .app-inspector-scroll { overflow: visible; }
  .app-inspector { inline-size: 100% !important; max-inline-size: 100%; }
}
